const POSTGREST = $env.POSTGREST_URL || 'https://postgrest-production-7960.up.railway.app';
const JWT = $env.POSTGREST_JWT;

const ticketId = $input.first().json.body?.ticket_id || $input.first().json.ticket_id;
if (!ticketId) throw new Error('Missing ticket_id in request body');

const ticketRes = await this.helpers.httpRequest({
  method: 'GET',
  url: POSTGREST + '/tickets?id=eq.' + ticketId + '&select=id,reference,title,supplier_id,supplier_name,submitted_by,submitted_by_email,value_eur,amount_eur',
  headers: { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' }
});
const ticket = Array.isArray(ticketRes) ? ticketRes[0] : ticketRes;
if (!ticket) throw new Error('Ticket not found: ' + ticketId);

let doc = null;
if (ticket.supplier_id) {
  const docsRes = await this.helpers.httpRequest({
    method: 'GET',
    url: POSTGREST + '/legal_documents?supplier_id=eq.' + ticket.supplier_id + '&status=in.(draft,pending_signature)&order=created_at.desc&limit=1',
    headers: { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' }
  });
  doc = Array.isArray(docsRes) && docsRes.length > 0 ? docsRes[0] : null;
}

return [{ json: { ticketId, ticket, doc } }];

const integrationKey = $env.DOCUSIGN_INTEGRATION_KEY;
const userId        = $env.DOCUSIGN_USER_ID;
const oauthUrl      = $env.DOCUSIGN_OAUTH_URL || 'https://account-d.docusign.com';
const rsaKey        = ($env.DOCUSIGN_RSA_PRIVATE_KEY || '').replace(/\\n/g, '\n');

if (!integrationKey || !userId || !rsaKey) {
  throw new Error('Missing DocuSign env vars');
}

const now = Math.floor(Date.now() / 1000);
const header  = Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64url');
const payload = Buffer.from(JSON.stringify({
  iss: integrationKey,
  sub: userId,
  aud: oauthUrl.replace('https://', ''),
  iat: now,
  exp: now + 3600,
  scope: 'signature impersonation'
})).toString('base64url');

const crypto = require('crypto');
const sign = crypto.createSign('RSA-SHA256');
sign.update(header + '.' + payload);
const sig = sign.sign(rsaKey, 'base64url');
const assertion = header + '.' + payload + '.' + sig;

const tokenRes = await this.helpers.httpRequest({
  method: 'POST',
  url: oauthUrl + '/oauth/token',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + assertion,
  returnFullResponse: true
});

if (tokenRes.statusCode !== 200) {
  throw new Error('DocuSign token error ' + tokenRes.statusCode + ': ' + JSON.stringify(tokenRes.body));
}

const accessToken = tokenRes.body.access_token;
const data = $('Fetch Ticket & Document').item.json;
return [{ json: { ...data, accessToken } }];

const { ticketId, ticket, doc, accessToken } = $input.first().json;
const accountId = $env.DOCUSIGN_ACCOUNT_ID;
const baseUrl   = $env.DOCUSIGN_BASE_URL || 'https://demo.docusign.net/restapi';
const intakeUrl = $env.INTAKE_URL || 'https://intake-production-84a0.up.railway.app';
const returnUrl = intakeUrl + '?signed=1&ticket=' + ticketId;

const signerName  = ticket.submitted_by  || 'TrueSpend User';
const signerEmail = ticket.submitted_by_email || 'eugnmueller@googlemail.com';
const clientUserId = ticketId;

let docBase64, docName, docExt;
if (doc && doc.content) {
  docBase64 = Buffer.from(doc.content).toString('base64');
  docName   = (doc.doc_type || 'document').toUpperCase() + ' — ' + (ticket.supplier_name || 'Supplier');
  docExt    = 'txt';
} else {
  const amount = ticket.value_eur || ticket.amount_eur || 0;
  const text = [
    'TRUESPEND PROCUREMENT DOCUMENT',
    '================================',
    '',
    'Ticket Reference : ' + ticket.reference,
    'Title            : ' + ticket.title,
    'Supplier         : ' + (ticket.supplier_name || '—'),
    'Value            : EUR ' + Number(amount).toLocaleString('de-DE', { minimumFractionDigits: 2 }),
    '',
    'By signing this document, the signatory confirms review and approval',
    'of the above procurement action in accordance with TrueSpend policy.',
    '',
    'Signature:  ________________________   Date: _______________',
    '',
    'Printed Name: ________________________',
  ].join('\n');
  docBase64 = Buffer.from(text).toString('base64');
  docName   = 'Procurement Approval — ' + ticket.reference;
  docExt    = 'txt';
}

const envelope = {
  emailSubject: 'Please sign: ' + ticket.title,
  documents: [{ documentBase64: docBase64, name: docName, fileExtension: docExt, documentId: '1' }],
  recipients: {
    signers: [{
      email: signerEmail,
      name: signerName,
      clientUserId,
      recipientId: '1',
      tabs: {
        signHereTabs:   [{ documentId: '1', pageNumber: '1', xPosition: '100', yPosition: '400' }],
        dateSignedTabs: [{ documentId: '1', pageNumber: '1', xPosition: '100', yPosition: '440' }]
      }
    }]
  },
  status: 'sent'
};

const envRes = await this.helpers.httpRequest({
  method: 'POST',
  url: baseUrl + '/v2.1/accounts/' + accountId + '/envelopes',
  headers: { 'Authorization': 'Bearer ' + accessToken, 'Content-Type': 'application/json' },
  body: JSON.stringify(envelope),
  returnFullResponse: true
});

if (envRes.statusCode !== 201) {
  throw new Error('DocuSign envelope error ' + envRes.statusCode + ': ' + JSON.stringify(envRes.body));
}

const envelopeId = envRes.body.envelopeId;

const viewRes = await this.helpers.httpRequest({
  method: 'POST',
  url: baseUrl + '/v2.1/accounts/' + accountId + '/envelopes/' + envelopeId + '/views/recipient',
  headers: { 'Authorization': 'Bearer ' + accessToken, 'Content-Type': 'application/json' },
  body: JSON.stringify({ returnUrl, authenticationMethod: 'none', email: signerEmail, userName: signerName, clientUserId }),
  returnFullResponse: true
});

if (viewRes.statusCode !== 201) {
  throw new Error('DocuSign view URL error ' + viewRes.statusCode + ': ' + JSON.stringify(viewRes.body));
}

return [{ json: { ticketId, envelopeId, signingUrl: viewRes.body.url, ticket } }];

const POSTGREST = $env.POSTGREST_URL || 'https://postgrest-production-7960.up.railway.app';
const JWT = $env.POSTGREST_JWT;
const { ticketId, envelopeId, signingUrl, ticket } = $input.first().json;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: POSTGREST + '/trace_log',
    headers: { 'Authorization': 'Bearer ' + JWT, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
    body: JSON.stringify({
      signal: 'contract',
      value: 'DocuSign envelope ' + envelopeId + ' created for ticket ' + ticketId + ' (' + ticket.reference + '). Awaiting signature.',
      green: true,
      weight: 1.0,
      notes: 'Embedded signing URL generated. Signer: ' + (ticket.submitted_by_email || 'truespend user') + '.'
    })
  });
} catch (e) {
  console.log('Trace log warning:', e.message);
}

return [{ json: { ticketId, envelopeId, signingUrl } }];
